Method.Implementation:
Set tSC = $$$OK
//Current datetime in yyyymmddHHmmss format
Set dNow = $ZD($H,8)_$Translate($ZT($H,1),":","")

If ($Find(GS08Val,"005010X222")>=0)||($Find(GS08Val,"004010X098")>=0)
{
	Set Fname = "5010_SH_H_"_dNow_"_1"
}
ElseIf ($Find(GS08Val,"005010X223")>=0)||($Find(GS08Val,"004010X096")>=0)
{
	Set Fname = "5010_SH_U_"_dNow_"_1"
}
Else
{
	Set Fname = "SH_billing_MP_"_dNow_".txt_1"
}
Quit tSC
